function findResults(query){
 const results=[],seen=new Set();
 const add=(kind,id,targetStage)=>{id=String(id);const key=kind+':'+targetStage+':'+id;if(!seen.has(key)){seen.add(key);results.push({kind,id,stage:targetStage});}};
 const scoped=/^(?:scope[\s:#]*|sk[\s:#]*)(\d+)$/i.exec(query);if(scoped){if((model?.scopes||[]).some(s=>String(s.id)===scoped[1])&&(debugProfile()||!structuralScopeId(scoped[1])))add('scope',scoped[1],stage);return results;}
 const nodeQuery=/^(?:node|节点)[\s:#_]*(\d+)$/i.exec(query);if(nodeQuery){for(const target of [stage,stage==='before'?'after':'before'])if((model?.[target]?.nodes||[]).some(n=>String(n.id)===nodeQuery[1]&&(debugProfile()||graphNodeAllowed(n,target))))add('node',nodeQuery[1],target);return results;}
 // Fusion names identify a scope; only actual updated SK nodes establish a target.
 const exactAlias=/^sk_(\d+)$/i.exec(query);
 const scopes=new Set();
 for(const fusion of model?.fusions||[]){
  const sid=String(fusion.scope_id);
  const raw=String(fusion.label||'').toLowerCase(),alias=raw.startsWith('sk_'+sid)?raw:'sk_'+sid+(raw.startsWith('_')?'':'_')+raw;
  if((exactAlias?sid===exactAlias[1]:raw.includes(query)||alias.includes(query))&&(debugProfile()||!structuralScopeId(sid)))scopes.add(sid);
 }
 for(const node of model?.after?.nodes||[]){
  if(displaySK(node)&&(scopes.has(String(node.scope_id))||(exactAlias&&String(node.scope_id)===exactAlias[1])))add('node',node.id,'after');
 }
 for(const sid of scopes)if(!results.some(r=>r.kind==='node'&&(model.after?.nodes||[]).some(n=>String(n.id)===r.id&&String(n.scope_id)===sid)))add('scope',sid,'before');
 for(const targetStage of [stage,stage==='before'?'after':'before']){
  for(const n of model?.[targetStage]?.nodes||[])if((debugProfile()||graphNodeAllowed(n,targetStage))&&[n.id,n.label,n.type,n.scope_id].some(v=>String(v??'').toLowerCase().includes(query)))add('node',n.id,targetStage);
 }
 for(const scope of model?.scopes||[])if((debugProfile()||!structuralScopeId(scope.id))&&[scope.id,scope.label].some(v=>String(v??'').toLowerCase().includes(query)))add('scope',scope.id,stage);
 return results;
}
let searchQuery='';
function searchStep(direction=1){if(!model)return;const q=$('search').value.trim().toLowerCase();if(!q)return;
 if(q!==searchQuery||!searchResults.length){searchResults=findResults(q);searchIndex=-1;searchQuery=q;}
 const results=searchResults;if(!results.length){$('search-status').textContent='未找到匹配的 Task、SK 或 SK 融合函数';return;}
 const nextIndex=(searchIndex+direction+results.length)%results.length,result=results[nextIndex];
 if(result.kind==='node')navigate('node',result.id,result.stage,true,false);else jump({scope_id:result.id,stage:result.stage},false);
 searchResults=results;searchIndex=nextIndex;searchQuery=q;
 $('search-status').textContent=(nextIndex+1)+' / '+results.length+' · '+(result.kind==='scope'?'SK ':'节点 #')+result.id+' · '+(result.stage==='after'?'更新后':'更新前');
}
